function g(r){if(!r)return"-";const t=typeof r=="string"?new Date(r):r;if(isNaN(t.getTime()))return String(r);const e=n=>String(n).padStart(2,"0");return`${t.getFullYear()}-${e(t.getMonth()+1)}-${e(t.getDate())} ${e(t.getHours())}:${e(t.getMinutes())}:${e(t.getSeconds())}`}function i(r){if(!r)return"-";const t=typeof r=="string"?new Date(r):r;if(isNaN(t.getTime()))return String(r);const e=n=>String(n).padStart(2,"0");return`${t.getFullYear()}-${e(t.getMonth()+1)}-${e(t.getDate())}`}export{i as a,g as f};
